import {
	abandonTelemetry,
	drainBeforeTelemetryShutdown,
	shutdownTelemetry
} from './otel-instrumentation.js';
import { registerWebShutdown } from './web-shutdown.js';

registerWebShutdown(process, {
	waitFor: drainBeforeTelemetryShutdown,
	shutdown: shutdownTelemetry
});

// Register the drain before adapter-node starts accepting requests.
// The adapter artifact is generated by pnpm build, not part of the source graph.
// Its top level runs the server init hook, so a configuration fault rejects here;
// report it through the console bridge and flush before Node prints and exits.
try {
	await import(new URL('../build/index.js', import.meta.url).href);
} catch (error) {
	console.error('[web] failed to start:', error);
	await abandonTelemetry();
	throw error;
}
